    tags: ['土耳其', '竞争管理局', '谷歌', 'AI概览', 'AI模式', '反垄断', '新闻出版商', '临时措施', '流量替代', '出海合规'],
    link: 'https://news.qq.com/rain/a/20261102A0A86I00',
